Here is the root cause:
In `set_pmd_migration_entry()`, when handling non-present (softleaf/device-private) PMD entries, the function incorrectly uses `pmd_write()`, `pmd_soft_dirty()`, and `pmd_uffd_wp()` to determine the attributes for the migration entry. These macros interpret bits from a present PMD, but for softleaf entries the bit semantics differ; notably, on x86-64, `_PAGE_SWP_SOFT_DIRTY` is aliased to `_PAGE_RW`, causing `pmd_write()` to return the softdirty state instead of the writable state. This leads to a writable migration entry being installed when it should be read-only, corrupting rmap state and triggering assertion failures. The fundamental flaw is that the code does not use the appropriate softleaf-specific accessors (e.g., `softleaf_is_device_private_write()`, `pmd_swp_soft_dirty()`, `pmd_swp_uffd_wp()`).

Here is the patch:
 #ifdef CONFIG_ARCH_ENABLE_THP_MIGRATION
 int set_pmd_migration_entry(struct page_vma_mapped_walk *pvmw,
 		struct page *page)
 {
 	struct folio *folio = page_folio(page);
 	struct vm_area_struct *vma = pvmw->vma;
 	struct mm_struct *mm = vma->vm_mm;
 	unsigned long address = pvmw->address;
-	bool anon_exclusive;
+	bool anon_exclusive, present, writable, softdirty, uffd_wp;
 	pmd_t pmdval;
 	swp_entry_t entry;
 	pmd_t pmdswp;

 	if (!(pvmw->pmd && !pvmw->pte))
 		return 0;

-	flush_cache_range(vma, address, address + HPAGE_PMD_SIZE);
-	if (unlikely(!pmd_present(*pvmw->pmd)))
-		pmdval = pmdp_huge_get_and_clear(vma->vm_mm, address, pvmw->pmd);
-	else
+	present = pmd_present(*pvmw->pmd);
+	if (likely(present)) {
+		flush_cache_range(vma, address, address + HPAGE_PMD_SIZE);
+
 		pmdval = pmdp_invalidate(vma, address, pvmw->pmd);

+		writable = pmd_write(pmdval);
+		softdirty = pmd_soft_dirty(pmdval);
+		uffd_wp = pmd_uffd_wp(pmdval);
+	} else {
+		softleaf_t old_entry;
+
+		pmdval = pmdp_huge_get_and_clear(vma->vm_mm, address, pvmw->pmd);
+		old_entry = softleaf_from_pmd(pmdval);
+
+		writable = softleaf_is_device_private_write(old_entry);
+		softdirty = pmd_swp_soft_dirty(pmdval);
+		uffd_wp = pmd_swp_uffd_wp(pmdval);
+	}
